UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT X.* FROM   (VALUES (''All'', ''All''),(''Claimed'', ''Claimed''), (''Unclaimed'', ''Unclaimed''),(''Closed'', ''Closed'')) AS X ("label", "value")'::text WHERE
idashboardqueryid = 63;




